//! Module containing sample struct types generated by the IR macros:
//! [`IrGenerated`], [`IrMappingGenerated`], and [`IrKeplerGenerated`].
//!
//! Every item on the sample pages is the macro's own output for the declaration in this
//! file, so the pages show exactly what a declaration generates.

#[cfg(all(not(feature = "host"), target_os = "none"))]
use crate::{ir, ir_kepler, ir_mapping};

/// Sample button type for [`IrMappingGenerated`]: the keys a remote's codes map to.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum RemoteKeysGenerated {
    /// Power key.
    Power,
    /// Play key.
    Play,
    /// Stop key.
    Stop,
}

#[cfg(all(not(feature = "host"), target_os = "none"))]
ir! {
    pub IrGenerated { pin: GPIO1 }
}

#[cfg(all(not(feature = "host"), target_os = "none"))]
ir_mapping! {
    pub IrMappingGenerated {
        pin: GPIO3,
        button: RemoteKeysGenerated,
        capacity: 3,
    }
}

#[cfg(all(not(feature = "host"), target_os = "none"))]
ir_kepler! {
    pub IrKeplerGenerated { pin: GPIO5 }
}
